#include "RelationshipGraphRuntime.hpp"
namespace elysium::citizens {std::uint64_t RelationshipGraphRuntime::key(StableId a,StableId b){return(a*0x9e3779b97f4a7c15ULL)^(b+0xbf58476d1ce4e5b9ULL);}double RelationshipGraphRuntime::clamp(double v){return std::clamp(std::isfinite(v)?v:0.0,-1.0,1.0);}bool RelationshipGraphRuntime::upsert(RelationshipEdge e,std::string&w){if(!e.from||!e.to||e.from==e.to){w="invalid relationship";return false;}e.affinity=clamp(e.affinity);e.trust=clamp(e.trust);e.loyalty=clamp(e.loyalty);edges_[key(e.from,e.to)]=e;return true;}bool RelationshipGraphRuntime::apply(RelationshipDelta d,std::string&w){auto i=edges_.find(key(d.from,d.to));if(i==edges_.end()){w="missing edge";return false;}i->second.affinity=clamp(i->second.affinity+d.affinity);i->second.trust=clamp(i->second.trust+d.trust);i->second.loyalty=clamp(i->second.loyalty+d.loyalty);++i->second.revision;return true;}std::optional<RelationshipEdge>RelationshipGraphRuntime::get(StableId a,StableId b)const{auto i=edges_.find(key(a,b));if(i==edges_.end())return std::nullopt;return i->second;}}
